from queueing import payload

def submit(owner, enqueue, batch_size=20):
    # Validate integer 1..100, reject bool and invalid values with ValueError BEFORE enqueue
    if not isinstance(batch_size, int):
        # bool is subclass of int in Python, but bool should be rejected
        if isinstance(batch_size, bool):
            raise ValueError('batch_size must be an integer, not bool')
        raise ValueError('batch_size must be an integer')
    if batch_size < 1 or batch_size > 100:
        raise ValueError('batch_size must be between 1 and 100')
    return enqueue(payload(owner, batch_size))

def execute(task, process):
    batch_size = task.get('batch_size', 20)
    # validate batch_size here too? requirement says worker.execute uses it
    # but validation already done before enqueue, so task should have valid batch_size
    return process(task["owner"], batch_size)

from api import submit
from queueing import payload
from worker import execute

def test_default_batch_size():
    # mock enqueue that captures payload
    captured = []
    def mock_enqueue(p):
        captured.append(p)
    # submit with no batch_size should use default 20
    submit('owner1', mock_enqueue)
    assert captured[0]['owner'] == 'owner1'
    assert captured[0]['batch_size'] == 20

def test_explicit_batch_size():
    captured = []
    def mock_enqueue(p):
        captured.append(p)
    submit('owner2', mock_enqueue, batch_size=30)
    assert captured[0]['owner'] == 'owner2'
    assert captured[0]['batch_size'] == 30

def test_batch_size_low():
    captured = []
    def mock_enqueue(p):
        captured.append(p)
    submit('owner3', mock_enqueue, batch_size=1)
    assert captured[0]['batch_size'] == 1

def test_batch_size_high():
    captured = []
    def mock_enqueue(p):
        captured.append(p)
    submit('owner4', mock_enqueue, batch_size=100)
    assert captured[0]['batch_size'] == 100

def test_batch_size_invalid_bool():
    captured = []
    def mock_enqueue(p):
        captured.append(p)
    try:
        submit('owner5', mock_enqueue, batch_size=True)
        assert False, 'should raise ValueError'
    except ValueError as e:
        assert 'batch_size must be an integer' in str(e)

