def test_legacy_payload_without_batch_size():
    # simulate old payload creation (without batch_size) that gets passed to execute
    # worker.execute should use default 20
    task = {'owner': 'legacy'}
    # execute should use batch_size=20 default
    from worker import execute
    def dummy_process(owner, bs):
        return f'{owner}:{bs}'
    result = execute(task, dummy_process)
    assert result == 'legacy:20'

def test_worker_uses_batch_size():
    task = {'owner': 'test', 'batch_size': 42}
    def dummy_process(owner, bs):
        return f'{owner}:{bs}'
    from worker import execute
    result = execute(task, dummy_process)
    assert result == 'test:42'

if __name__ == '__main__':
    import sys
    # run all tests
    tests = [
        test_default_batch_size,
        test_explicit_batch_size,
        test_batch_size_low,
        test_batch_size_high,
        test_batch_size_invalid_bool,
        test_batch_size_invalid_float,
        test_batch_size_out_of_range_low,
        test_batch_size_out_of_range_high,
        test_legacy_payload_without_batch_size,
        test_worker_uses_batch_size,
    ]
    failed = []
    for test in tests:
        try:
            test()
        except Exception as e:
            failed.append((test.__name__, str(e)))
    if failed:
        print('Failed tests:')
        for name, err in failed:
            print(f'  {name}: {err}')
        sys.exit(1)
    else:
        print('All tests passed')
